package com.blockblastai;
import android.app.*;import android.os.*;import android.content.*;import android.provider.Settings;import android.widget.*;
public class MainActivity extends Activity {
 static final String[] KEYS={"boardX","boardY","boardSize","trayY","trayCell","dragOffset","emptyColor"};
 static final String[] DEFAULTS={"0.056","0.235","0.888","0.764","0.049","0.12","#50301D"};
 EditText[] fields=new EditText[KEYS.length];
 public void onCreate(Bundle b){super.onCreate(b);ScrollView sv=new ScrollView(this);LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(32,32,32,32);sv.addView(l);setContentView(sv);TextView t=new TextView(this);t.setText("BlockBlast AI • experimental\nCalibrare: coordonate proporționale cu ecranul. Culoarea celulei goale în format hex.");l.addView(t);for(int i=0;i<KEYS.length;i++){TextView label=new TextView(this);label.setText(KEYS[i]);l.addView(label);fields[i]=new EditText(this);fields[i].setSingleLine();fields[i].setText(getSharedPreferences("cfg",0).getString(KEYS[i],DEFAULTS[i]));l.addView(fields[i]);}add(l,"Salvează calibrarea",()->{try{for(int i=0;i<6;i++)Float.parseFloat(fields[i].getText().toString());android.graphics.Color.parseColor(fields[6].getText().toString());}catch(Exception e){Toast.makeText(this,"Valori invalide",0).show();return;}var ed=getSharedPreferences("cfg",0).edit();for(int i=0;i<KEYS.length;i++)ed.putString(KEYS[i],fields[i].getText().toString());ed.apply();});add(l,"Activează serviciul Android",()->startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS)));add(l,"Instrucțiuni",()->new AlertDialog.Builder(this).setMessage("Activează serviciul, apoi deschide Block Blast. Panoul flotant apare doar în joc. Hint indică mutarea; Auto o execută. Stop oprește automatizarea. Calibrarea implicită este orientativă.").setPositiveButton("OK",null).show());}
 void add(LinearLayout l,String s,Runnable r){Button b=new Button(this);b.setText(s);b.setOnClickListener(v->r.run());l.addView(b);}
}
